-- =====================================================================
-- Más ejercicios para el catálogo: los que Manu usaba en su app anterior
-- y no estaban (con su nombre, sin video todavía).
-- =====================================================================
insert into public.exercises (name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues)
select v.* from (values
('Burpee','resistencia',array['Cuerpo completo']::text[],array['Solo peso corporal']::text[],false,'De pie, bajá a cuclillas, apoyá las manos y llevá los pies atrás a plancha. Hacé una flexión, volvé los pies hacia las manos y terminá con un salto con brazos arriba.','Core firme en la plancha. Caé suave. Ritmo constante.'),
('Escalador','core',array['Core','Hombros','Cadera']::text[],array['Solo peso corporal']::text[],false,'En plancha alta, llevá una rodilla al pecho y alterná las piernas rápido sin que se mueva la cadera.','Manos debajo de los hombros. Cadera baja y quieta. Respirá.'),
('Estocada con salto','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Solo peso corporal']::text[],false,'Desde posición de estocada, saltá y cambiá de pierna en el aire para caer en estocada con la otra adelante.','Caé suave y controlado. Rodilla delantera en línea con el pie. Torso erguido.'),
('Estocada frontal','fuerza',array['Cuádriceps','Glúteos']::text[],array['Solo peso corporal','Mancuernas']::text[],true,'Dá un paso largo hacia adelante y bajá hasta que ambas rodillas queden cerca de 90°. Empujá con la pierna de adelante para volver.','Torso erguido. Rodilla delantera alineada con el pie. Paso estable.'),
('Estocada en diagonal','fuerza',array['Cuádriceps','Glúteos','Aductores']::text[],array['Solo peso corporal','Mancuernas']::text[],true,'Dá un paso en diagonal hacia adelante (unos 45°), bajá controlado y volvé al centro empujando con esa pierna.','Pie y rodilla apuntando hacia la dirección del paso. Cadera atrás. Control al volver.'),
('Estocada frontal con rotación','core',array['Cuádriceps','Glúteos','Oblicuos']::text[],array['Solo peso corporal','Mancuernas','Balón medicinal']::text[],true,'Hacé una estocada hacia adelante y, abajo, girá el torso hacia el lado de la pierna adelantada con la carga frente al pecho. Volvé al centro y subí.','Gira el torso, no la rodilla. Cadera estable. Movimiento controlado.'),
('Rotación de torso con peso','core',array['Oblicuos','Core','Columna torácica']::text[],array['Mancuernas','Balón medicinal','Poleas']::text[],false,'De pie en postura atlética, sostené el peso frente al pecho y rotá el torso de un lado al otro dejando que la cadera acompañe.','Brazos firmes. Rotación desde el torso. Pies apoyados.'),
('Peso muerto en equilibrio','estabilidad',array['Isquiotibiales','Glúteos','Core']::text[],array['Solo peso corporal','Mancuernas','Kettlebells']::text[],true,'Parado en una pierna, inclinate hacia adelante desde la cadera llevando la otra pierna atrás hasta quedar casi paralelo al piso. Volvé controlado.','Cadera nivelada. Espalda neutra. Rodilla de apoyo apenas flexionada.'),
('Salto desde rodillas','potencia',array['Glúteos','Cuádriceps','Cadera']::text[],array['Solo peso corporal']::text[],false,'Arrodillado con los pies en punta, llevá la cadera atrás y saltá extendiendo la cadera con fuerza para caer de pie en cuclillas.','Impulso de cadera explosivo. Brazos ayudan. Caé estable.'),
('Salto en una pierna, caída en dos','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Solo peso corporal']::text[],true,'Impulsate con una sola pierna y caé con las dos piernas, amortiguando y quedando estable.','Caída silenciosa. Rodillas alineadas. Frená 2 segundos abajo.'),
('Salto buscando distancia','potencia',array['Glúteos','Cuádriceps','Isquiotibiales']::text[],array['Solo peso corporal']::text[],false,'Desde parado, llevá la cadera atrás con los brazos y saltá hacia adelante lo más lejos posible, cayendo con las dos piernas.','Brazos atrás y adelante con fuerza. Extensión completa. Caída estable.'),
('Salto con giro','potencia',array['Glúteos','Cuádriceps','Oblicuos']::text[],array['Solo peso corporal']::text[],false,'Saltá hacia arriba girando el cuerpo (un cuarto o media vuelta) y caé estable mirando hacia la nueva dirección.','Gira con hombros y cadera juntos. Caé suave. Controlá antes del próximo.'),
('Salto en dos tiempos','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Solo peso corporal']::text[],false,'Hacé un primer salto corto y, apenas caés, encadená un segundo salto más alto o más largo.','Contacto corto con el piso entre saltos. Brazos coordinados. Caída estable.'),
('Swing con giro','potencia',array['Glúteos','Isquiotibiales','Oblicuos']::text[],array['Kettlebells','Mancuernas']::text[],false,'Como un swing con pesa, empujá con la cadera y en la subida rotá el torso hacia un lado; alterná el lado en cada repetición.','La fuerza sale de la cadera. Espalda neutra. Rotación controlada.'),
('Swing en polea','velocidad',array['Oblicuos','Core','Cadera']::text[],array['Poleas']::text[],false,'En postura de golf con la polea a un costado, hacé el gesto del swing contra la resistencia, rotando cadera y torso.','Secuencia cadera-torso-brazos. Postura de golf. Velocidad con control.'),
('Swing en potencia','velocidad',array['Cuerpo completo']::text[],array['Palo de golf']::text[],false,'Hacé swings completos con tu palo buscando la máxima velocidad posible, descansando entre cada uno.','Máxima intención. Buena secuencia. Pocas repeticiones con buen descanso.'),
('Sentadilla sin peso','fuerza',array['Cuádriceps','Glúteos']::text[],array['Solo peso corporal']::text[],false,'Pies al ancho de hombros, bajá llevando la cadera atrás y abajo hasta donde mantengas la espalda neutra. Subí empujando el piso.','Talones apoyados. Rodillas en la línea de los pies. Pecho alto.'),
('Sentadilla con salto','potencia',array['Cuádriceps','Glúteos','Pantorrillas']::text[],array['Solo peso corporal']::text[],false,'Bajá a media sentadilla y saltá lo más alto posible. Caé suave y encadená la siguiente.','Brazos ayudan. Caída silenciosa. Rodillas alineadas.'),
('Sentadilla sumo','fuerza',array['Glúteos','Aductores','Cuádriceps']::text[],array['Kettlebells','Mancuernas']::text[],false,'Pies más abiertos que los hombros y puntas hacia afuera, con la pesa colgando entre las piernas. Bajá con el torso erguido y subí.','Rodillas hacia afuera. Torso erguido. Talones apoyados.'),
('Bajada al cajón','fuerza',array['Cuádriceps','Glúteos']::text[],array['Cajón pliométrico']::text[],true,'Parado sobre el cajón en una pierna, bajá lento la otra hasta tocar el piso con el talón y volvé a subir.','Bajada lenta. Rodilla alineada con el pie. Cadera nivelada.'),
('Extensión de cuádriceps en máquina','fuerza',array['Cuádriceps']::text[],array['Máquinas de gimnasio']::text[],false,'Sentado en la máquina, extendé las rodillas hasta casi estirarlas y bajá controlado.','Espalda apoyada. Subida firme, bajada lenta. Sin rebotes.'),
('Aducción en máquina','fuerza',array['Aductores']::text[],array['Máquinas de gimnasio']::text[],false,'Sentado en la máquina, cerrá las piernas contra la resistencia y abrí controlado.','Espalda apoyada. Recorrido completo. Bajada lenta.'),
('Patada de glúteo en máquina','fuerza',array['Glúteos']::text[],array['Máquinas de gimnasio','Poleas']::text[],true,'Con el pie en la plataforma o tobillera, llevá la pierna hacia atrás extendiendo la cadera y volvé controlado.','No arquees la zona lumbar. Apretá el glúteo arriba. Movimiento controlado.'),
('Prensa','fuerza',array['Cuádriceps','Glúteos']::text[],array['Máquinas de gimnasio']::text[],false,'Sentado en la prensa con los pies al ancho de hombros, bajá la plataforma flexionando las rodillas y empujá hasta casi extenderlas.','Zona lumbar apoyada. No bloquees las rodillas. Rodillas alineadas con los pies.'),
('Puente de glúteo con mancuerna','fuerza',array['Glúteos','Isquiotibiales']::text[],array['Mancuernas']::text[],false,'Acostado boca arriba con rodillas flexionadas y la mancuerna sobre la cadera, elevá la cadera hasta alinear rodillas, cadera y hombros. Bajá controlado.','Apretá glúteos arriba. Costillas abajo. Empujá con los talones.'),
('Extensión lumbar en banco','fuerza',array['Lumbares','Glúteos','Isquiotibiales']::text[],array['Banco','Máquinas de gimnasio']::text[],false,'En el banco de lumbares, bajá el torso flexionando la cadera y subí hasta quedar alineado, sin pasarte hacia atrás.','Movimiento desde la cadera. No hiperextiendas. Controlado.'),
('Superman','core',array['Lumbares','Glúteos','Espalda alta']::text[],array['Solo peso corporal']::text[],false,'Boca abajo con brazos estirados adelante, elevá a la vez brazos, pecho y piernas unos centímetros y sostené.','Mirada al piso. Elevación corta. Glúteos apretados.'),
('Superman alternado','core',array['Lumbares','Glúteos','Espalda alta']::text[],array['Solo peso corporal']::text[],false,'Boca abajo con brazos adelante, elevá brazo derecho y pierna izquierda, bajá y alterná.','Cuello largo. Movimiento lento. Cadera apoyada.'),
('Plancha con alcance','core',array['Core','Hombros']::text[],array['Solo peso corporal']::text[],false,'En plancha alta, llevá una mano hacia adelante como alcanzando algo, volvé y alterná, sin que rote la cadera.','Pies algo separados. Cadera quieta. Core firme.'),
('Remo en plancha con mancuerna','core',array['Dorsales','Core','Hombros']::text[],array['Mancuernas']::text[],true,'En plancha alta con las manos sobre mancuernas, remá una hacia la cadera manteniendo el cuerpo quieto. Alterná.','Pies separados. Cadera nivelada. Codo pegado al cuerpo.'),
('Tríceps en plancha','fuerza',array['Tríceps','Core','Hombros']::text[],array['Solo peso corporal']::text[],false,'Desde plancha sobre antebrazos, subí a plancha alta apoyando una mano y después la otra; volvé a antebrazos y alterná el brazo que empieza.','Cadera quieta. Core firme. Manos debajo de los hombros.'),
('Flexiones inclinadas','fuerza',array['Pectorales','Tríceps','Hombros']::text[],array['Banco','Solo peso corporal']::text[],false,'Con las manos sobre un banco o superficie elevada, hacé flexiones manteniendo el cuerpo recto.','Cuerpo en línea. Codos a 45°. Pecho al borde.'),
('Flexiones declinadas','fuerza',array['Pectorales','Hombros','Tríceps']::text[],array['Banco','Solo peso corporal']::text[],false,'Con los pies sobre un banco y manos en el piso, hacé flexiones manteniendo el cuerpo recto.','Core firme. No hundas la cadera. Codos a 45°.'),
('Flexiones con salto','potencia',array['Pectorales','Tríceps','Hombros']::text[],array['Solo peso corporal']::text[],false,'Bajá como en una flexión y empujá explosivo para despegar las manos del piso (con aplauso si podés). Caé con los codos suaves.','Cuerpo rígido. Empuje explosivo. Caída amortiguada.'),
('Flexiones de hombros','fuerza',array['Hombros','Tríceps']::text[],array['Solo peso corporal']::text[],false,'Con la cadera alta formando una V invertida, flexioná los codos llevando la cabeza hacia el piso entre las manos y empujá para subir.','Cadera alta. Codos hacia atrás. Bajada controlada.'),
('Fondos en banco','fuerza',array['Tríceps','Hombros']::text[],array['Banco']::text[],false,'Con las manos en el borde de un banco detrás tuyo, bajá flexionando los codos y subí extendiéndolos.','Hombros lejos de las orejas. Cadera cerca del banco. Codos hacia atrás.'),
('Fondos en paralelas','fuerza',array['Pectorales','Tríceps','Hombros']::text[],array['Máquinas de gimnasio']::text[],false,'En las paralelas, bajá flexionando los codos con el torso algo inclinado hacia adelante y subí.','Hombros abajo. Bajá hasta donde no moleste el hombro. Control.'),
('Press inclinado con barra','fuerza',array['Pectorales','Hombros','Tríceps']::text[],array['Barra y discos','Banco','Rack']::text[],false,'En banco inclinado, bajá la barra a la parte alta del pecho y empujá hasta extender los brazos.','Escápulas juntas. Pies firmes. Codos a 45°.'),
('Press de pecho sentado en polea','fuerza',array['Pectorales','Tríceps','Hombros']::text[],array['Poleas','Máquinas de gimnasio']::text[],false,'Sentado con las manijas a la altura del pecho, empujá hacia adelante hasta extender los brazos y volvé controlado.','Espalda apoyada. Escápulas atrás. Control en la vuelta.'),
('Press de pecho de pie en polea','fuerza',array['Pectorales','Core','Tríceps']::text[],array['Poleas']::text[],false,'De pie entre las poleas, un pie adelante, empujá las manijas hacia adelante y volvé controlado.','Core firme. No arquees la espalda. Codos a 45°.'),
('Cruce en polea','fuerza',array['Pectorales','Hombros']::text[],array['Poleas']::text[],false,'De pie entre las poleas altas, con codos apenas flexionados, juntá las manos adelante y abajo y volvé abriendo controlado.','Codos fijos. Pecho alto. Movimiento lento.'),
('Pullover con mancuerna','fuerza',array['Dorsales','Pectorales','Core']::text[],array['Mancuernas','Banco']::text[],false,'Acostado en un banco con la mancuerna sobre el pecho, llevala hacia atrás por encima de la cabeza con los brazos casi extendidos y volvé.','Costillas abajo. Codos apenas flexionados. Rango cómodo para el hombro.'),
('Elevación frontal con mancuerna','fuerza',array['Hombros']::text[],array['Mancuernas']::text[],false,'De pie, elevá las mancuernas hacia adelante hasta la altura de los hombros y bajá controlado.','Sin balanceo. Codos apenas flexionados. Hombros abajo.'),
('Extensión de hombro con mancuerna','fuerza',array['Hombros','Espalda alta']::text[],array['Mancuernas']::text[],true,'Con el torso algo inclinado, llevá la mancuerna hacia atrás con el brazo casi extendido y volvé controlado.','Torso quieto. Hombro lejos de la oreja. Movimiento lento.'),
('Press de hombros en máquina','fuerza',array['Hombros','Tríceps']::text[],array['Máquinas de gimnasio']::text[],false,'Sentado en la máquina, empujá las manijas hacia arriba hasta casi extender los brazos y bajá controlado.','Espalda apoyada. Costillas abajo. Sin bloquear codos.'),
('Jalón tras nuca','fuerza',array['Dorsales','Espalda alta']::text[],array['Poleas','Máquinas de gimnasio']::text[],false,'Sentado en el jalón, bajá la barra por detrás de la cabeza hasta la nuca y subí controlado. Solo si tenés buena movilidad de hombro.','Cabeza levemente adelante. Rango cómodo. Escápulas abajo.'),
('Remo sentado en polea','fuerza',array['Dorsales','Espalda alta','Bíceps']::text[],array['Poleas','Máquinas de gimnasio']::text[],false,'Sentado con la espalda recta, tirá de la manija hacia el abdomen juntando las escápulas y volvé controlado.','Torso quieto. Codos cerca del cuerpo. Pecho alto.'),
('Dominada supina','fuerza',array['Dorsales','Bíceps']::text[],array['Solo peso corporal']::text[],false,'Colgado de la barra con las palmas hacia vos, subí hasta pasar el mentón por arriba y bajá controlado.','Escápulas abajo antes de tirar. Sin balanceo. Bajada completa.'),
('Curl de bíceps con barra','fuerza',array['Bíceps','Antebrazos']::text[],array['Barra y discos']::text[],false,'De pie con la barra en agarre supino, flexioná los codos subiendo la barra al pecho y bajá controlado.','Codos pegados al cuerpo. Sin balanceo. Bajada lenta.'),
('Curl de bíceps con barra W','fuerza',array['Bíceps','Antebrazos']::text[],array['Barra y discos']::text[],false,'De pie con la barra W, flexioná los codos subiendo la barra y bajá controlado.','Codos fijos. Torso quieto. Bajada lenta.'),
('Curl de bíceps en banco inclinado','fuerza',array['Bíceps']::text[],array['Barra y discos','Mancuernas','Banco']::text[],false,'Apoyado boca abajo en un banco inclinado con los brazos colgando, flexioná los codos y bajá controlado.','Brazos colgando verticales. Sin impulso. Recorrido completo.'),
('Curl de bíceps en polea','fuerza',array['Bíceps']::text[],array['Poleas']::text[],false,'De pie frente a la polea baja, flexioná los codos subiendo la manija y bajá controlado.','Codos pegados. Tensión constante. Sin balanceo.'),
('Curl de bíceps sentado','fuerza',array['Bíceps']::text[],array['Mancuernas','Banco']::text[],false,'Sentado con una mancuerna en cada mano, flexioná los codos y bajá controlado.','Espalda apoyada. Codos fijos. Bajada lenta.'),
('Curl concentrado','fuerza',array['Bíceps']::text[],array['Mancuernas','Banco']::text[],true,'Sentado con el codo apoyado en la cara interna del muslo, flexioná el codo subiendo la mancuerna y bajá lento.','Codo quieto. Sin impulso. Apretá arriba.'),
('Tríceps en polea alta','fuerza',array['Tríceps']::text[],array['Poleas']::text[],false,'De pie frente a la polea alta, extendé los codos empujando hacia abajo y volvé controlado.','Codos pegados al cuerpo. Torso quieto. Extensión completa.'),
('Tríceps a un brazo en polea','fuerza',array['Tríceps']::text[],array['Poleas']::text[],true,'Con una mano en la polea alta, extendé el codo hacia abajo y volvé controlado. Cambiá de brazo.','Codo fijo al costado. Hombro abajo. Movimiento lento.'),
('Caminata o trote en cinta','resistencia',array['Cuerpo completo']::text[],array['Máquinas de gimnasio']::text[],false,'Caminá o troteá en la cinta a la velocidad e inclinación indicadas, el tiempo indicado.','Ritmo en el que puedas hablar (salvo que se indique otra cosa). Postura erguida.')
) as v(name, category, muscle_groups, equipment, unilateral, instructions, coaching_cues)
where not exists (select 1 from public.exercises e where e.org_id is null and e.name = v.name);
